import * as React from "react"

import { cn } from "@/lib/utils"

/**
 * Baselines where the words will be. Still by default; a pencil stroke reads
 * along each line only while an ancestor has aria-busy="true" (and motion is welcome).
 */
function Skeleton({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="skeleton" aria-hidden="true" className={cn("db-skeleton", className)} {...props} />
}

type SkeletonLineProps = React.ComponentProps<"i"> & {
  /** Any CSS width; the default is the full line. */
  width?: string
  /** Any CSS height; the default is one line of text. */
  height?: string
  /** Position in the stack, so the stroke reads down the lines in turn. */
  index?: number
}

function SkeletonLine({ width, height, index = 0, className, style, ...props }: SkeletonLineProps) {
  return (
    <i
      data-slot="skeleton-line"
      className={className}
      style={{ "--w": width, "--lh": height, "--i": index, ...style } as React.CSSProperties}
      {...props}
    />
  )
}

/** Where an avatar or a mark will be. */
function SkeletonRing({ size, className, style, ...props }: React.ComponentProps<"span"> & { size?: string }) {
  return (
    <span
      data-slot="skeleton-ring"
      className={cn("db-skeleton-ring", className)}
      style={{ "--s": size, ...style } as React.CSSProperties}
      {...props}
    />
  )
}

export { Skeleton, SkeletonLine, SkeletonRing, type SkeletonLineProps }

@layer components {
  /* ── db-skeleton ── baselines where the words will be */
  .db-skeleton { display: grid; }
  .db-skeleton > i { position: relative; display: block; width: var(--w, 100%); height: var(--lh, 1.7em); overflow: clip; background: linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) no-repeat 0 100% / 100% var(--db-hairline); }
  .db-skeleton > i::after { content: ""; position: absolute; inset: auto 0 0; height: var(--db-stroke); background: linear-gradient(90deg, transparent, var(--db-pencil) 50%, transparent) no-repeat -60% 0 / 30% 100%; }
  /* While it loads, a pencil stroke reads along each line in turn. */
  [aria-busy="true"] .db-skeleton > i::after { animation: db-read 1600ms var(--db-breath) infinite; animation-delay: calc(var(--i, 0) * 140ms); }
  @keyframes db-read { from { background-position: -60% 0; } to { background-position: 160% 0; } }
  .db-skeleton-ring { display: block; width: var(--s, 2.75rem); height: var(--s, 2.75rem); border-radius: 50%; box-shadow: inset 0 0 0 var(--db-hairline) var(--db-rule-strong); }
  @media (prefers-reduced-motion: reduce) { [aria-busy="true"] .db-skeleton > i::after { animation: none; } }
}
